 public async ValueTask<bool>UpdateAsync(string original,EmployeeInput x,CancellationToken t){await using var c=await Open(t);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(t);await using var cmd=Cmd("""UPDATE [dbo].[Empleado] SET [Cedula]=@Identification,[Nombre]=@Name,[Telefono1]=@Phone1,[Telefono2]=@Phone2,[Puesto]=@Position,[Salario]=@Salary,[FechaIngreso]=@HireDate,[Codigo]=@Code,[CodRuta]=@Route,[Correo]=@Email,[TimeLab_Anios]=@Years,[TimeLab_Meses]=@Months,[TimeLab_Dias]=@Days,[DiasTotalesDeVacacionesGanadas]=@Earned,[DiasTotalesDeVacacionesConsumidas]=@Used,[txtb_DiasTotalesDeVacacionesPendientes]=@Pending,[CuentaBancaria]=@Bank,[IdColaborador]=@Collaborator,[CuentaContable]=@Ledger,[CategoriaEmpleado]=@Category WHERE [Cedula]=@Original AND ISNULL([Estado],0)=0""",c,tx);EmployeeParameters(cmd,x);P(cmd,"@Original",100,original);if(await cmd.ExecuteNonQueryAsync(t)!=1)return false;await MovePhotoAsync(c,tx,original,x.Identification,t);await SavePhotoAsync(c,tx,x.Identification,x.Photo,t);await tx.CommitAsync(t);return true;}
